const b = ($input.first().json || {}).body;
const bad = error => [{ json: { valid: false, error } }];
if (!b || typeof b !== 'object' || Array.isArray(b)) return bad('JSON object body required');
const TYPES = ['created', 'first_response', 'pause', 'resume', 'resolve'];
if (!TYPES.includes(b.type)) return bad('type must be one of: ' + TYPES.join(', '));
if (typeof b.external_id !== 'string' || !/^[A-Za-z0-9_.:-]{1,100}$/.test(b.external_id)) return bad('external_id must be 1-100 characters of A-Z a-z 0-9 _ . : -');
const clean = (v, max) => typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, max) : '';
const out = { valid: true, type: b.type, external_id: b.external_id, subject: '', customer: '', priority: '', assignee: '' };
if (b.type === 'created') {
  out.subject = clean(b.subject, 200);
  if (!out.subject) return bad('subject is required for "created"');
  out.customer = clean(b.customer, 100);
  out.assignee = clean(b.assignee, 100);
  out.priority = b.priority === undefined ? 'normal' : String(b.priority).toLowerCase();
  if (!/^[a-z]{3,20}$/.test(out.priority)) return bad('priority must be 3-20 lowercase letters');
}
return [{ json: out }];

