// ---------- business calendar maths (time zone and DST aware, no external libraries) ----------
const _fmt = {};
const partsOf = (ms, tz) => {
  const f = _fmt[tz] || (_fmt[tz] = new Intl.DateTimeFormat('en-CA', { timeZone: tz, hourCycle: 'h23',
    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }));
  const o = {};
  for (const p of f.formatToParts(new Date(ms))) o[p.type] = p.value;
  return { y: +o.year, m: +o.month, d: +o.day, h: +o.hour % 24, mi: +o.minute, s: +o.second };
};
const tzOffsetMs = (ms, tz) => {
  const p = partsOf(ms, tz);
  return Date.UTC(p.y, p.m - 1, p.d, p.h, p.mi, p.s) - Math.floor(ms / 1000) * 1000;
};
// Wall-clock time in a zone -> UTC milliseconds (two passes settle the offset around DST changes)
const localToUtc = (y, m, d, minutes, tz) => {
  const wall = Date.UTC(y, m - 1, d, 0, minutes);
  const first = wall - tzOffsetMs(wall, tz);
  return wall - tzOffsetMs(first, tz);
};
const pad2 = n => String(n).padStart(2, '0');
const buildCal = (row, policyCalendar) => {
  if (policyCalendar === '24x7') return { type: '24x7' };
  const tz = String(row.timezone || '');
  try { new Intl.DateTimeFormat('en-CA', { timeZone: tz }); } catch (e) { throw new Error('invalid time zone "' + tz + '"'); }
  const workDays = (Array.isArray(row.work_days) ? row.work_days : []).map(Number).filter(n => n >= 1 && n <= 7);
  const startMin = Number(row.start_minute), endMin = Number(row.end_minute);
  if (!workDays.length) throw new Error('no working days configured');
  if (!(startMin >= 0 && endMin <= 1440 && startMin < endMin)) throw new Error('invalid working hours');
  return { type: 'business', tz, workDays, startMin, endMin, holidays: new Set((row.holidays || []).map(String)) };
};
// Opening window (UTC ms) of the local calendar day starting at UTC-midnight value dayMs, or null when closed
const windowOf = (dayMs, cal) => {
  const dt = new Date(dayMs);
  const y = dt.getUTCFullYear(), m = dt.getUTCMonth() + 1, d = dt.getUTCDate();
  const dow = (dt.getUTCDay() + 6) % 7 + 1;
  if (!cal.workDays.includes(dow) || cal.holidays.has(y + '-' + pad2(m) + '-' + pad2(d))) return null;
  return [localToUtc(y, m, d, cal.startMin, cal.tz), localToUtc(y, m, d, cal.endMin, cal.tz)];
};
const dayStartOf = (ms, tz) => { const p = partsOf(ms, tz); return Date.UTC(p.y, p.m - 1, p.d); };
const DAY = 86400000;
// Business minutes between two instants (fractional)
const bizMinutes = (aMs, bMs, cal) => {
  if (!(bMs > aMs)) return 0;
  if (cal.type === '24x7') return (bMs - aMs) / 60000;
  let total = 0, n = 0;
  for (let t = dayStartOf(aMs, cal.tz), last = dayStartOf(bMs, cal.tz); t <= last && n < 1100; t += DAY, n++) {
    const w = windowOf(t, cal);
    if (!w) continue;
    const lo = Math.max(aMs, w[0]), hi = Math.min(bMs, w[1]);
    if (hi > lo) total += (hi - lo) / 60000;
  }
  return total;
};
// The instant at which `mins` business minutes have elapsed after startMs
const addBizMinutes = (startMs, mins, cal) => {
  if (!(mins > 0)) return startMs;
  if (cal.type === '24x7') return startMs + mins * 60000;
  let left = mins;
  for (let t = dayStartOf(startMs, cal.tz), n = 0; n < 800; t += DAY, n++) {
    const w = windowOf(t, cal);
    if (!w) continue;
    const from = Math.max(startMs, w[0]);
    if (from >= w[1]) continue;
    const avail = (w[1] - from) / 60000;
    if (left <= avail) return from + left * 60000;
    left -= avail;
  }
