const iso = ms => new Date(Math.round(ms)).toISOString();
const S = v => (v === null || v === undefined) ? '' : (Object.prototype.toString.call(v) === '[object Date]' ? v.toISOString() : String(v));
const r3 = x => Math.round(x * 1000) / 1000;

const ev = $('Parse Event').first().json;
const t = $('Find Ticket').first().json || {};
const pol = $input.first().json || {};
const reject = (status, error) => [{ json: { ok: false, status, error } }];
if (ev.type !== 'created' && !t.id) return reject(404, 'ticket not found');
if (!pol.priority) return reject(400, 'unknown priority (no SLA policy)');
let cal;
try { cal = buildCal(pol, pol.calendar); } catch (e) { return reject(500, 'calendar misconfigured: ' + e.message); }
