    if (cur.status !== 'open') return conflict('only an open ticket can be paused (status is ' + cur.status + ')');
    next.status = 'pending';
    next.remResp = cur.fr ? '' : String(r3(Math.max(0, bizMinutes(now, dResp, cal))));
    next.remRes = String(r3(Math.max(0, bizMinutes(now, dRes, cal))));
    next.dResp = ''; next.dRes = '';
  } else if (ev.type === 'resume') {
    if (cur.status !== 'pending') return conflict('only a pending ticket can be resumed (status is ' + cur.status + ')');
    next.status = 'open';
    next.dResp = (cur.fr || next.remResp === '') ? '' : iso(addBizMinutes(now, Number(next.remResp), cal));
    next.dRes = iso(addBizMinutes(now, Number(next.remRes), cal));
    next.remResp = ''; next.remRes = '';
  } else if (ev.type === 'resolve') {
    if (cur.status === 'resolved') return conflict('ticket is already resolved');
    const open = cur.status === 'open';
    next.rMet = String(open ? now <= dRes : Number(cur.remRes) > 0);
    if (!cur.fr) { next.fr = iso(now); next.frMet = String(open ? now <= dResp : Number(cur.remResp) > 0); }
    next.status = 'resolved'; next.rAt = iso(now);
    next.dResp = ''; next.dRes = ''; next.remResp = ''; next.remRes = '';
  }
} catch (e) { return reject(500, e.message); }
